const raw = $input.first().json;
const d = raw.body || raw;
const serviceType = d.serviceType || '';

let min = 0, max = 0, manual_review = false;

if (serviceType === 'car_detailing') {
  const base = {
    sedan:  { min: 250, max: 350 },
    suv:    { min: 300, max: 420 },
    van:    { min: 350, max: 480 },
    truck:  { min: 380, max: 520 },
    wagon:  { min: 270, max: 370 }
  }[d.vehicleType] || { min: 250, max: 380 };

  min = base.min;
  max = base.max;

  if (d.condition === 'average') { min += 40; max += 60; }
  if (d.condition === 'poor')    { min += 80; max += 120; }

  if (d.addon === 'ceramic_coat')     { min += 150; max += 200; manual_review = true; }
  if (d.addon === 'paint_protection') { min += 80;  max += 120; }
  if (d.addon === 'full_interior')    { min += 60;  max += 90; }

  const farSuburbs = ['dandenong','frankston','cranbourne','pakenham','sunbury','melton'];
  if (farSuburbs.includes((d.suburb || '').toLowerCase())) { min += 30; max += 50; }

} else if (serviceType === 'cleaning') {
  const base = {
    regular_clean:   { min: 80,  max: 150 },
    deep_clean:      { min: 200, max: 380 },
    end_of_lease:    { min: 350, max: 580 },
    airbnb_turnover: { min: 100, max: 200 },
    office_clean:    { min: 150, max: 300 }
  }[d.serviceType] || { min: 80, max: 200 };

  min = base.min;
  max = base.max;

  const beds  = parseInt(d.bedrooms)  || 2;
  const baths = parseInt(d.bathrooms) || 1;
  const roomExtra = (beds - 2) * 20 + (baths - 1) * 15;
  min += Math.max(0, roomExtra);
  max += Math.max(0, roomExtra);

  if (d.propertyType === 'house')      { min += 20; max += 40; }
  if (d.propertyType === 'commercial') { min += 50; max += 100; manual_review = true; }

  if (d.frequency === 'weekly')      { min = Math.round(min * 0.85); max = Math.round(max * 0.85); }
  if (d.frequency === 'fortnightly') { min = Math.round(min * 0.9);  max = Math.round(max * 0.9); }

  const farSuburbs = ['dandenong','frankston','cranbourne','pakenham','sunbury','melton'];
  if (farSuburbs.includes((d.suburb || '').toLowerCase())) { min += 30; max += 50; }

} else {
  throw new Error('Unknown serviceType: ' + serviceType);
}

return [{ json: { quote_min: min, quote_max: max, manual_review } }];
